    91	    /// An HLG signal's light, in cd/m², as a grey at BT.2100's nominal
    92	    /// 1,000 cd/m² display: 1000·E^1.2, E the HLG inverse OETF (scene light).
    93	    static func hlgNits(_ signal: Double) -> Double {
    94	        let a = 0.17883277
    95	        let b = 1 - 4 * a
    96	        let c = 0.5 - a * log(4 * a)
    97	        let v = max(signal, 0)
    98	        let scene = v <= 0.5 ? v * v / 3 : (exp((v - c) / a) + b) / 12
    99	        return 1000 * pow(scene, 1.2)
