     1	//
     2	//  Waveform.metal — the four scopes' passes (spec §11 GR-5, GR-10): the luma
     3	//  waveform, the RGB parade, the Rec. 709 vectorscope and the R′G′B′Y′
     4	//  histogram. Owned by `app/Sources/WaveformAnalyzer.swift`, which dispatches
     5	//  one thread per pixel of a composited frame for each shown scope and reads
     6	//  each scope's counts back.
     7	//
     8	//  Nothing here touches `Compositor.metal` or `LayerUniforms`: every pass
     9	//  reads a FINISHED frame (the compositor's destination, or a rendered image)
    10	//  and writes only its own counts buffer.
    11	//
    12	//  **The counting rule** (GR-10): never one global atomic per pixel into a
    13	//  counter a picture region shares. The waveform spreads by column, so it
    14	//  adds globally; the parade counts each 8-px-wide threadgroup's two column
    15	//  bins in threadgroup memory (GR-10's fallback, taken in G2-1); the
    16	//  vectorscope counts its central 64 × 64 bins (where grey and near-grey
    17	//  pixels land) in threadgroup memory and the rest globally, a non-central
    18	//  bin shared by a whole SIMD group added once (GR-26's same-bin add: a flat
    19	//  saturated colour); the histogram counts in threadgroup memory. Each
    20	//  threadgroup merges its counts once, and a threadgroup kernel guards its
    21	//  pixel read rather than returning before its barriers.
    22	//
    23	//  **The signal** (spec §11 HD-15 (e)): the waveform, the vectorscope and the
    24	//  histogram take a 0/1 `signal` uniform. 0 is Rec. 709's constants, the
    25	//  expressions T4-0 counted, unchanged in text; 1, an HLG project's frame, is
    26	//  BT.2020's weights and matrix. The weights are constants chosen by it,
    27	//  never uniforms, so the SDR arm's arithmetic is the one S12 holds.
    28	//
    29	
    30	#include <metal_stdlib>
    31	using namespace metal;
    32	
    33	// Rec. 709 luma weights, on the ENCODED (sRGB) values: Y′, what the person
    34	// sees, not linear luminance.
    35	constant float3 kLumaWeights = float3(0.2126, 0.7152, 0.0722);
    36	// BT.2020's, for an HLG project's signal (HD-15 (e)).
    37	constant float3 kLuma2020Weights = float3(0.2627, 0.6780, 0.0593);
    38	
    39	// One pixel into its (column bin, level) cell. The column bin is the pixel's
    40	// x scaled to 256; the level is Y′ of the saturated colour rounded to 0…255,
    41	// so level 255 is exactly "an 8-bit file writes 255" (Y′ ≥ 254.5/255) and
    42	// level 0 is Y′ < 0.5/255. `counts` is `column * 256 + level`; `signal` 1
    43	// takes BT.2020's weights.
    44	kernel void framejob_waveform_bin(texture2d<half, access::read> frame [[texture(0)]],
    45	                                 device atomic_uint *counts [[buffer(0)]],
    46	                                 constant uint &signal [[buffer(1)]],
    47	                                 uint2 gid [[thread_position_in_grid]]) {
    48	    uint width = frame.get_width();
    49	    if (gid.x >= width || gid.y >= frame.get_height()) {
    50	        return;
    51	    }
    52	    float3 rgb = saturate(float3(frame.read(gid).rgb));
    53	    uint level;
    54	    if (signal == 1u) {
    55	        level = min(255u, uint(dot(rgb, kLuma2020Weights) * 255.0 + 0.5));
    56	    } else {
    57	        level = min(255u, uint(dot(rgb, kLumaWeights) * 255.0 + 0.5));
    58	    }
    59	    uint column = gid.x * 256u / width;
    60	    atomic_fetch_add_explicit(&counts[column * 256u + level], 1u, memory_order_relaxed);
    61	}
    62	
    63	// A saturated encoded value's level, GR-5's rule: round(255·v), 0…255.
    64	static inline uint scopeLevel(float v) {
    65	    return min(255u, uint(v * 255.0 + 0.5));
    66	}
