    68	// The parade's threadgroup: 8 pixels across (`WaveformAnalyzer.paradeAcross`),
    69	// which in a frame 1792 px wide or more (7 × 256) spans at most two of the
    70	// 256 column bins.
    71	constant uint kParadeBands = 2u;
    72	// Two copies of each threadgroup cell, alternate threads adding to
    73	// alternate copies, so neighbours on one flat run contend half as often.
    74	constant uint kParadeCopies = 2u;
    75	
    76	// R′, G′ and B′ each binned as the waveform bins Y′: `counts` is
    77	// `(channel * 256 + column) * 256 + level`, channel 0 R′, 1 G′, 2 B′. GR-10's
    78	// per-band threadgroup counts: a group spanning at most `kParadeBands`
    79	// column bins counts its pixels in threadgroup memory and merges once per
    80	// group, non-zero only; a group spanning more (some groups of a frame under
    81	// 1792 px wide) adds globally, as the waveform does. Taken in G2-1 because the global
    82	// parade's 4K time sat within 7 % of GR-10's bound.
    83	kernel void framejob_parade_bin(texture2d<half, access::read> frame [[texture(0)]],
    84	                               device atomic_uint *counts [[buffer(0)]],
    85	                               uint2 gid [[thread_position_in_grid]],
    86	                               uint index [[thread_index_in_threadgroup]],
    87	                               uint2 group [[threads_per_threadgroup]]) {
    88	    const uint cells = kParadeBands * 3u * 256u;
    89	    threadgroup atomic_uint local[kParadeBands * 3u * 256u * kParadeCopies];
    90	    uint width = frame.get_width();
    91	    uint threads = group.x * group.y;
    92	    uint originX = gid.x - index % group.x;
    93	    uint first = originX * 256u / width;
    94	    uint last = min(originX + group.x - 1u, width - 1u) * 256u / width;
    95	    bool banded = last - first < kParadeBands;
    96	    if (banded) {
    97	        for (uint i = index; i < cells * kParadeCopies; i += threads) {
    98	            atomic_store_explicit(&local[i], 0u, memory_order_relaxed);
    99	        }
   100	    }
