   103	        float3 rgb = saturate(float3(frame.read(gid).rgb));
   104	        uint column = gid.x * 256u / width;
   105	        uint copy = index % kParadeCopies;
   106	        for (uint channel = 0u; channel < 3u; channel++) {
   107	            uint level = scopeLevel(rgb[channel]);
   108	            if (banded) {
   109	                uint cell = (channel * kParadeBands + column - first) * 256u + level;
