    54	/// the six HDR rows, each 10-bit for an HDR picture (`vp9_webm` is 8-bit only
    55	/// at `sdr`). Every other video row of an HLG project writes the SDR version.
    56	pub(crate) const HDR_ROWS: [&str; 6] = [
    57	    "hevc_10bit",
    58	    "av1",
    59	    "av1_webm",
    60	    "vp9_webm",
    61	    "prores_422",
    62	    "prores_4444",
    63	];
